// All artwork is drawn on low-resolution canvases with a repeatable palette.
function seeded(seed){return ()=>((seed=Math.imul(seed,1664525)+1013904223|0)>>>0)/4294967296}
function surface(w,h,draw){const c=document.createElement('canvas');c.width=w;c.height=h;const g=c.getContext('2d');g.imageSmoothingEnabled=false;draw(g);return c}
function rect(g,color,x,y,w,h){g.fillStyle=color;g.fillRect(Math.floor(x),Math.floor(y),Math.ceil(w),Math.ceil(h))}
function poly(g,c,points){g.fillStyle=c;g.beginPath();points.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.closePath();g.fill()}
const bottle=surface(18,42,g=>{
 rect(g,'#181410',5,0,8,12);rect(g,'#c4a067',5,1,8,3);rect(g,'#896438',6,5,6,7);
 poly(g,'#743f19',[[5,11],[13,11],[16,17],[16,39],[14,41],[3,41],[1,38],[1,17]]);
 rect(g,'#ae7034',3,17,2,21);rect(g,'#d4a457',2,19,14,15);rect(g,'#256346',3,20,12,12);rect(g,'#e7ce84',4,22,10,2);rect(g,'#b7ad6c',6,27,6,1)
});
const cafe=surface(112,87,g=>{
 rect(g,'#29262a',8,27,97,60);rect(g,'#151923',9,40,95,47);
 for(let y=40;y<87;y+=4)rect(g,'#2d2a2d',9,y,95,1);
 poly(g,'#101823',[[0,36],[12,23],[99,21],[111,32],[110,36]]);rect(g,'#684440',3,34,106,2);
 rect(g,'#191a21',20,6,70,21);rect(g,'#923d38',20,5,70,1);rect(g,'#743b38',20,26,70,1);
 g.textAlign='center';g.font='bold 16px monospace';g.shadowBlur=5;g.shadowColor='#ff4a37';g.fillStyle='#ff8264';g.fillText('ФРЕГАТ',55,22);g.shadowBlur=0;
 for(let x of [15,73]){rect(g,'#64483e',x,46,23,25);rect(g,'#ba7647',x+2,48,19,20);rect(g,'#d9965c',x+3,50,16,8);rect(g,'#433330',x+10,46,2,25);rect(g,'#513b32',x,56,23,2)}
 rect(g,'#6b554b',44,44,22,43);rect(g,'#24272b',46,46,18,41);rect(g,'#9a704f',49,49,12,18);rect(g,'#c8a77b',59,72,2,2)
});
function pine(g,x,y,h,c,r){rect(g,c,x-1,y-h,2,h);for(let j=5;j<h-2;j+=2){let half=(j/h)*h*.23*(.55+r()*.45);rect(g,c,x-half,y-h+j,half*2,2+r()*3)}}
