function loadPicture(src){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=reject;image.src=src})}
let rider,poster;
const lamp=surface(48,112,c=>{
 rect(c,'#151817',22,25,4,87);rect(c,'#776647',22,25,1,86);rect(c,'#34342a',18,109,12,3);
 poly(c,'#514337',[[15,12],[33,12],[30,25],[18,25]]);rect(c,'#ffbd68',18,13,12,9);rect(c,'#fff1bc',20,13,8,8);
 rect(c,'#423a2d',23,12,2,12);poly(c,'#242727',[[12,12],[16,9],[23,4],[26,4],[36,12]]);rect(c,'#9a805b',23,2,2,3)
});
function glow(c,x,y,r,hot,mid){const light=c.createRadialGradient(x,y,0,x,y,r);light.addColorStop(0,hot);light.addColorStop(.23,mid);light.addColorStop(1,'rgba(255,153,66,0)');c.fillStyle=light;c.fillRect(x-r,y-r,r*2,r*2)}
function makePoster(photo){
 return surface(960,540,c=>{
   c.drawImage(photo,0,0,960,540);
   const pixels=c.getImageData(0,0,960,540),data=pixels.data;
   const lights=[[817,289,115],[390,318,48],[97,332,40]];
   for(let y=0;y<540;y++)for(let x=0;x<960;x++){
     const i=(y*960+x)*4;let lit=0;
     for(const [lx,ly,r] of lights){const a=(x-lx)/r,b=(y-ly)/(r*1.16);lit+=Math.max(0,1-a*a-b*b)**2}
     const luma=(data[i]*.28+data[i+1]*.54+data[i+2]*.18);
     data[i]=luma*.075+data[i]*lit*.94;data[i+1]=luma*.11+data[i+1]*lit*.71;data[i+2]=luma*.15+data[i+2]*lit*.43;
   }
   c.putImageData(pixels,0,0);
   for(const [x,y,r] of lights){rect(c,'#191d1d',x-12,y-5,24,6);rect(c,'#ffda91',x-9,y,18,3);glow(c,x,y+1,r*.5,'#ffe4ac8a','#faab4d2a')}
   // A park lantern lights the rider and lays a warm pool across the entrance.
   c.save();c.translate(743,494);c.scale(1,.18);glow(c,0,0,158,'#e4a55a62','#c18d4b38');c.restore();
   c.drawImage(lamp,723,155,144,336);glow(c,795,204,107,'#fff0bd90','#ffc27638');
   c.fillStyle='#020502b0';c.beginPath();c.ellipse(685,498,67,7,0,0,2*Math.PI);c.fill();
   c.drawImage(rider,613,193,146,305)
 })
}
