const interior=surface(800,440,c=>{
 const r=seeded(72);
 const wood=(x,y,w,h,base,grain)=>{rect(c,base,x,y,w,h);for(let i=0;i<w*h/72;i++)rect(c,grain,x+r()*w,y+r()*h,Math.min(w*.13,1+r()*20),1)};
 rect(c,'#29251e',0,0,800,440);
 for(let y=28;y<292;y+=14){rect(c,'#584b37',0,y,800,12);for(let x=(y%28?-23:0);x<800;x+=48)rect(c,'#433c2e',x,y,2,13)}
 // Ceiling beams in perspective.
 poly(c,'#201d19',[[0,0],[800,0],[800,22],[0,67]]);for(let x=20;x<800;x+=150)poly(c,'#3a2d21',[[x,0],[x+35,0],[x-45,46],[x-56,46]]);
 // The door to the park, beyond rain-streaked glass.
 wood(286,76,126,213,'#382e25','#52402c');rect(c,'#121d21',297,88,104,131);
 for(let i=0;i<40;i++)pine(c,297+r()*102,209,12+r()*42,'#1b302e',r);
 rect(c,'#735b39',344,88,4,130);rect(c,'#745d3e',297,170,104,4);rect(c,'#b4a276',390,229,5,3);
 for(let i=0;i<25;i++)rect(c,'#8ca29944',297+r()*101,91+r()*114,1,2+r()*4);
 // Shelves, glassware and an old enamel cafe sign.
 for(let row=0;row<2;row++){let y=158+row*50;wood(435,y,172,8,'#30261c','#93744a');for(let j=0;j<13;j++){let h=17+r()*16;rect(c,['#383e27','#714e2e','#7f7350'][j%3],443+j*12,y-h,6,h);rect(c,'#888664',445+j*12,y-h-5,2,5);rect(c,'#c0a77c',444+j*12,y-h*.54,4,4)}}
 rect(c,'#342b21',620,64,143,83);rect(c,'#bba373',623,67,137,77);rect(c,'#314942',626,70,131,71);c.textAlign='center';c.fillStyle='#d9c9a0';c.font='12px Georgia';c.fillText('кафе-бар',692,95);c.font='italic bold 30px Georgia';c.fillText('Фрегат',692,124);
 // Counter and seven delivered bottles in the foreground.
 poly(c,'#83603a',[[0,276],[800,245],[800,325],[0,365]]);for(let i=0;i<2100;i++){let x=r()*800;rect(c,'#c19d6330',x,278-x*.04+r()*47,2+r()*19,1)}
 poly(c,'#39291e',[[0,364],[800,325],[800,440],[0,440]]);for(let x=0;x<800;x+=41){rect(c,'#5f4430',x,366-x*.05,2,100)}
 for(let i=0;i<7;i++){let x=431+i*41,y=235+Math.sin(i*1.8)*4;c.fillStyle='#31291f';c.beginPath();c.ellipse(x+14,y+56,17,3,0,0,Math.PI*2);c.fill();c.drawImage(bottle,x,y,25,57)}
 for(let x of [125,530,701]){rect(c,'#171816',x,0,2,34);poly(c,'#222923',[[x-22,51],[x-9,34],[x+9,34],[x+22,51]]);rect(c,'#ffe3ad',x-18,51,36,3);glow(c,x,57,112,'#fff0bb53','#ffbc702b')}
 const shadow=c.createLinearGradient(0,0,800,0);shadow.addColorStop(0,'#0f100ee6');shadow.addColorStop(.56,'#0f100e22');shadow.addColorStop(1,'#0f100e00');c.fillStyle=shadow;c.fillRect(0,0,800,440)
});
